      P.vein = tq < 0.35 ? 0 : tq < 0.8 ? 1 : 2; P.sw = tq >= 0.7 ? 1 : 0; P.ix = 2; P.pup = tq < 0.5 ? 1 : 0; P.gem = tq < 0.5 ? 1 : (f12 & 1) ? 2 : 1; P.rim = 1; P.leg = tq > 0.9 ? 2 : 0;
