      for (let k = 0; k < len * rs * 0.5; k++) { U.dot(E, x, y, m.vein, P.vein === 0 ? 2 : P.vein === 1 ? 3 : 4); x -= Math.cos(a); y -= Math.sin(a); a += bend * 0.5; }
      U.dot(E, x + Math.sin(a), y - Math.cos(a), m.vein, P.vein === 2 ? 3 : 2);
