    if ((state === IDLE && P.gem > 0) || state === RECOVER) { emberAcc += dt * (state === IDLE ? 4 : 8); while (emberAcc >= 1) { emberAcc -= 1; spawn(K_EMBER, gx + Math.round(Math.random() * 2 - 1), gy - 2, Math.random() * 8 - 4, -7 - Math.random() * 6, 0.5 + Math.random() * 0.4, R_EL); } }
