    if (auraT < 1.9 && E.state !== CHARGE) { const q = auraT / 1.9, rx = 27 - 3 * q; if (!(q > 0.6 && (f12 & 1))) ellipse(HX - 6, FLOOR + 1, rx, 3, f12 >> 1, q < 0.3 ? EL[1] : EL[2], EL[3], q < 0.5 ? 5 : 2); }
